const ENIGMA_WIRING = {
  I:   'EKMFLGDQVZNTOWYHXUSPAIBRCJ',
  II:  'AJDKSIRUXBLHWTMCQGZNPYFVOE',
  III: 'BDFHJLCPRTXVZNYEIWGAKMUSQO',
  REF: 'YRUHQSLDPXNGOKMIEBFZCWVJAT',
};
const ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';

const WORD_TABLE = {
  A:['albatross','approach','ace'],   B:['birdie','bogey','bunker'],
  C:['caddy','chip','course'],        D:['divot','dogleg','driver'],
  E:['eagle','embed','escrow'],       F:['fairway','flop','flag'],
  G:['green','grip','gimme'],         H:['handicap','hazard','hole'],
  I:['iron','inside','index'],        J:['jigger','juniper','joint'],
  K:['knock','knoll','keeper'],       L:['links','lie','loft'],
  M:['mashie','mulligan','marker'],   N:['niblick','net','nap'],
  O:['open','out','oath'],            P:['par','putt','pin'],
  Q:['qualify','quest','quad'],       R:['rough','round','ridge'],
  S:['stroke','scratch','slope'],     T:['tee','tap','triple'],
  U:['under','uphill','uneven'],      V:['vault','vantage','vector'],
  W:['wedge','water','waggle'],       X:['xeric','xerox','xenon'],
  Y:['yardage','yips','yield'],       Z:['zone','zenith','zero'],
};

const rotorVals = [0, 0, 0];

function adjRotor(idx, delta) {
  rotorVals[idx] = ((rotorVals[idx] + delta) % 26 + 26) % 26;
  syncRotorDisplay(idx);
}

function setRotor(idx, val) {
  const n = parseInt(val);
  if (!isNaN(n)) rotorVals[idx] = ((n % 26) + 26) % 26;
  syncRotorDisplay(idx);
}

function syncRotorDisplay(idx) {
  document.getElementById('rd' + idx).textContent = rotorVals[idx];
  document.getElementById('rm' + idx).value = rotorVals[idx];
}

function enigmaEncode(r1, r2, r3) {
  function fwd(ch, wiring, offset) {
    return wiring[(ALPHA.indexOf(ch) + offset + 26) % 26];
  }
  function ref(ch) { return ENIGMA_WIRING.REF[ALPHA.indexOf(ch)]; }
  return ['G','O','L'].map(seed => {
    let c = seed;
    c = fwd(c, ENIGMA_WIRING.I,   r1 % 26);
    c = fwd(c, ENIGMA_WIRING.II,  r2 % 26);
    c = fwd(c, ENIGMA_WIRING.III, r3 % 26);
    c = ref(c);
    c = fwd(c, ENIGMA_WIRING.III, (26 - r3 % 26) % 26);
    return c;
  });
}

function renderWordTable(highlight = []) {
  const tbody = document.getElementById('wtBody');
  if (!tbody) return;
  // highlight[i] = letter → index rule: [0,1,0]
  const idxRule = [0, 1, 0];
  tbody.innerHTML = Object.entries(WORD_TABLE).map(([letter, words]) => {
    const hi = highlight.indexOf(letter);  // -1 or 0,1,2
    const isHl = hi !== -1;
    const cells = words.map((w, i) => {
      // badge if this is the word selected for the phrase
      const badge = isHl && idxRule[hi] === i
        ? `<span class="wt-idx">${i}</span>` : '';
      return `<td>${w}${badge}</td>`;
    }).join('');
    return `<tr class="${isHl ? 'wt-hl' : ''}"><td>${letter}</td>${cells}</tr>`;
  }).join('');
}

async function runEnigma() {
  const [r1, r2, r3] = rotorVals;

  // call the API so it logs
  let letters;
  try {
    const res = await fetch('/api/enigma/encode', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({r1, r2, r3}),
    });
    const d = await res.json();
    letters = d.output;
  } catch(e) {
    // fallback: compute locally
    letters = enigmaEncode(r1, r2, r3);
  }

  // Display output letters
  const outEl = document.getElementById('outLetters');
  outEl.innerHTML = letters.map(l => `<div class="out-letter">${l}</div>`).join('');
  document.getElementById('outHint').textContent =
    `Letters: ${letters.join(' · ')}  →  Row ${letters[0]}[0] · Row ${letters[1]}[1] · Row ${letters[2]}[0]`;
  document.getElementById('enigmaOut').classList.add('on');

  // Derive phrase
  const phrase = [
    WORD_TABLE[letters[0]][0],
    WORD_TABLE[letters[1]][1],
    WORD_TABLE[letters[2]][0],
  ];
  document.getElementById('pbPhrase').textContent = phrase.join(' · ');
  document.getElementById('phraseBox').classList.add('on');

  // Highlight word table
  renderWordTable(letters);
  // Switch to show word table if it's off-screen — just scroll to it
